B=[
('الرِّحْلَةُ الثَّانِيَةُ: الشَّوْقُ إِلَى الْبَحْرِ','İkinci yolculuk: Deniz özlemi',[
('فِي الْيَوْمِ التَّالِي جَاءَ الْحَمَّالُ، فَأَجْلَسَهُ السِّنْدِبَادُ بِجَانِبِهِ.','Ertesi gün hamal geldi; Sindbad onu yanına oturttu.'),
('قَالَ: «عِشْتُ فِي بَغْدَادَ زَمَنًا فِي رَاحَةٍ وَسُرُورٍ.»','Dedi ki: “Bağdat’ta bir süre rahat ve sevinç içinde yaşadım.”'),
('«لَكِنَّ قَلْبِي كَانَ يَشْتَاقُ إِلَى الْبَحْرِ وَالسَّفَرِ.»','“Ama kalbim denizi ve yolculuğu özlüyordu.”'),
('«فَاشْتَرَيْتُ بِضَاعَةً جَدِيدَةً، وَذَهَبْتُ إِلَى الْبَصْرَةِ مَرَّةً أُخْرَى.»','“Yeni mal aldım ve bir kez daha Basra’ya gittim.”'),
('«وَرَكِبْتُ سَفِينَةً جَدِيدَةً مَعَ تُجَّارٍ مِنْ بِلَادٍ مُخْتَلِفَةٍ.»','“Farklı memleketlerden tüccarlarla yeni bir gemiye bindim.”'),
('«سَافَرْنَا مِنْ جَزِيرَةٍ إِلَى جَزِيرَةٍ، نَبِيعُ وَنَشْتَرِي.»','“Adadan adaya yol aldık; alıp satıyorduk.”'),
('«حَتَّى وَصَلْنَا إِلَى جَزِيرَةٍ جَمِيلَةٍ، فِيهَا أَشْجَارٌ وَأَنْهَارٌ، وَلَيْسَ فِيهَا أَحَدٌ.»','“Sonunda ağaçları ve nehirleri olan ama içinde kimsenin olmadığı güzel bir adaya vardık.”')]),
('النَّوْمُ تَحْتَ الشَّجَرَةِ','Ağacın altında uyku',[
('«نَزَلَ التُّجَّارُ يَتَمَشَّوْنَ فِي الْجَزِيرَةِ.»','“Tüccarlar adada gezinmek için indi.”'),
('«أَمَّا أَنَا فَجَلَسْتُ تَحْتَ شَجَرَةٍ كَبِيرَةٍ عِنْدَ عَيْنِ مَاءٍ.»','“Bense bir pınarın yanında büyük bir ağacın altına oturdum.”'),
('«أَكَلْتُ قَلِيلًا، وَكَانَ الْهَوَاءُ لَطِيفًا، فَنِمْتُ.»','“Biraz yedim; hava hoştu ve uyudum.”'),
('«وَلَمَّا اسْتَيْقَظْتُ، لَمْ أَجِدْ أَحَدًا!»','“Uyandığımda kimseyi bulamadım!”'),
('«نَظَرْتُ إِلَى الْبَحْرِ، فَرَأَيْتُ السَّفِينَةَ بَعِيدَةً جِدًّا.»','“Denize baktım ve gemiyi çok uzakta gördüm.”'),
('«نَسِيَنِي التُّجَّارُ، وَسَافَرَتِ السَّفِينَةُ بِدُونِي!»','“Tüccarlar beni unutmuştu; gemi bensiz gitmişti!”'),
('«فَبَكَيْتُ وَقُلْتُ لِنَفْسِي: لِمَاذَا لَمْ تَبْقَ فِي بَغْدَادَ؟»','“Ağladım ve kendime dedim ki: Neden Bağdat’ta kalmadın?”')]),
('الْقُبَّةُ الْبَيْضَاءُ','Beyaz kubbe',[
('«صَعِدْتُ شَجَرَةً عَالِيَةً، وَنَظَرْتُ يَمِينًا وَشِمَالًا.»','“Yüksek bir ağaca tırmandım ve sağa sola baktım.”'),
('«فَرَأَيْتُ شَيْئًا أَبْيَضَ كَبِيرًا، كَأَنَّهُ قُبَّةٌ.»','“Büyük, beyaz, sanki bir kubbe gibi bir şey gördüm.”'),
('«نَزَلْتُ وَمَشَيْتُ إِلَيْهِ، وَدُرْتُ حَوْلَهُ.»','“İndim, ona doğru yürüdüm ve etrafında dolaştım.”'),
('«كَانَ أَمْلَسَ جِدًّا، وَلَيْسَ لَهُ بَابٌ.»','“Çok pürüzsüzdü ve kapısı yoktu.”'),
('«وَفَجْأَةً أَظْلَمَتِ الشَّمْسُ، كَأَنَّ سَحَابَةً كَبِيرَةً جَاءَتْ.»','“Birden güneş karardı; sanki büyük bir bulut gelmişti.”'),
('«رَفَعْتُ رَأْسِي، فَرَأَيْتُ طَائِرًا عَظِيمًا جِدًّا، جَنَاحَاهُ يُغَطِّيَانِ السَّمَاءَ.»','“Başımı kaldırdım ve kanatları göğü örten çok büyük bir kuş gördüm.”'),
('«فَعَرَفْتُ أَنَّ الْقُبَّةَ بَيْضَةٌ، وَأَنَّ هَذَا هُوَ طَائِرُ الرُّخِّ.»','“Kubbenin bir yumurta, bunun da Rûh kuşu olduğunu anladım.”')]),
('طَائِرُ الرُّخِّ','Rûh kuşu',[
('«نَزَلَ الطَّائِرُ وَجَلَسَ عَلَى بَيْضَتِهِ وَنَامَ.»','“Kuş indi, yumurtasının üstüne oturdu ve uyudu.”'),
('«فَكَّرْتُ وَقُلْتُ: هَذَا الطَّائِرُ يَطِيرُ إِلَى بِلَادٍ فِيهَا نَاسٌ.»','“Düşündüm ve dedim ki: Bu kuş, insanların olduğu yerlere uçar.”'),
('«فَخَلَعْتُ عِمَامَتِي، وَرَبَطْتُ نَفْسِي بِرِجْلِ الطَّائِرِ.»','“Sarığımı çıkardım ve kendimi kuşun ayağına bağladım.”'),
('«وَفِي الصَّبَاحِ طَارَ الرُّخُّ، فَطِرْتُ مَعَهُ بَيْنَ السَّمَاءِ وَالْأَرْضِ!»','“Sabah Rûh kuşu uçtu; ben de onunla gök ile yer arasında uçtum!”'),
('«كُنْتُ خَائِفًا جِدًّا، فَأَغْمَضْتُ عَيْنَيَّ.»','“Çok korkuyordum, gözlerimi kapadım.”'),
('«ثُمَّ نَزَلَ الطَّائِرُ عَلَى جَبَلٍ عَالٍ، فَفَكَكْتُ الْعِمَامَةَ بِسُرْعَةٍ.»','“Sonra kuş yüksek bir dağa kondu; ben de sarığı çabucak çözdüm.”'),
('«أَخَذَ الرُّخُّ حَيَّةً كَبِيرَةً فِي رِجْلَيْهِ، وَطَارَ بَعِيدًا.»','“Rûh kuşu ayaklarıyla büyük bir yılan kaptı ve uzaklara uçtu.”')]),
('وَادِي الْأَلْمَاسِ','Elmas vadisi',[
('«نَظَرْتُ حَوْلِي، فَإِذَا أَنَا فِي وَادٍ عَمِيقٍ بَيْنَ جِبَالٍ عَالِيَةٍ.»','“Etrafıma baktım; meğer yüksek dağlar arasında derin bir vadideymişim.”'),
('«وَكَانَتِ الْأَرْضُ كُلُّهَا حِجَارَةً تَلْمَعُ فِي الشَّمْسِ.»','“Yerin tamamı güneşte parlayan taşlardı.”'),
('«أَخَذْتُ حَجَرًا، فَعَرَفْتُ أَنَّهُ أَلْمَاسٌ!»','“Bir taş aldım ve onun elmas olduğunu anladım!”'),
('«لَكِنِّي رَأَيْتُ أَيْضًا حَيَّاتٍ كَبِيرَةً بَيْنَ الْحِجَارَةِ.»','“Ama taşların arasında büyük yılanlar da gördüm.”'),
('«كَانَتِ الْحَيَّاتُ تَخْتَبِئُ فِي النَّهَارِ مِنَ الرُّخِّ، وَتَخْرُجُ فِي اللَّيْلِ.»','“Yılanlar gündüz Rûh kuşundan saklanır, gece çıkardı.”'),
('«فَقُلْتُ: هَرَبْتُ مِنَ الْجَزِيرَةِ، فَوَقَعْتُ فِي مَكَانٍ أَصْعَبَ!»','“Dedim ki: Adadan kaçtım, ama daha zor bir yere düştüm!”'),
('«وَفِي اللَّيْلِ دَخَلْتُ مَغَارَةً صَغِيرَةً، وَسَدَدْتُ بَابَهَا بِحَجَرٍ.»','“Gece küçük bir mağaraya girdim ve ağzını bir taşla kapattım.”'),
('«وَلَمْ أَنَمْ حَتَّى الصَّبَاحِ مِنَ الْخَوْفِ.»','“Korkudan sabaha kadar uyumadım.”')]),
('قِطَعُ اللَّحْمِ','Et parçaları',[
('«فِي الصَّبَاحِ سَقَطَتْ قِطْعَةُ لَحْمٍ كَبِيرَةٌ أَمَامِي!»','“Sabah önüme büyük bir et parçası düştü!”'),
('«ثُمَّ سَقَطَتْ قِطْعَةٌ ثَانِيَةٌ، وَثَالِثَةٌ.»','“Sonra ikinci, üçüncü bir parça düştü.”'),
('«فَتَذَكَّرْتُ قِصَّةً سَمِعْتُهَا مِنَ التُّجَّارِ.»','“Tüccarlardan duyduğum bir hikâyeyi hatırladım.”'),
('«قَالُوا: النَّاسُ لَا يَسْتَطِيعُونَ النُّزُولَ إِلَى وَادِي الْأَلْمَاسِ.»','“Dediler ki: İnsanlar elmas vadisine inemez.”'),
('«فَيَرْمُونَ قِطَعَ اللَّحْمِ مِنْ فَوْقِ الْجَبَلِ، فَيَلْتَصِقُ بِهَا الْأَلْمَاسُ.»','“Bu yüzden dağın tepesinden et parçaları atarlar; elmaslar etlere yapışır.”'),
('«ثُمَّ تَأْتِي النُّسُورُ فَتَحْمِلُ اللَّحْمَ إِلَى أَعْلَى الْجَبَلِ.»','“Sonra kartallar gelip eti dağın tepesine taşır.”'),
('«فَيَصِيحُ النَّاسُ، فَتَطِيرُ النُّسُورُ، وَيَأْخُذُونَ الْأَلْمَاسَ.»','“İnsanlar bağırır, kartallar uçar ve onlar elmasları alır.”')]),
('النَّجَاةُ مِنَ الْوَادِي','Vadiden kurtuluş',[
('«مَلَأْتُ جُيُوبِي وَحِزَامِي بِأَحْسَنِ الْأَلْمَاسِ.»','“Ceplerimi ve kuşağımı en güzel elmaslarla doldurdum.”'),
('«ثُمَّ رَبَطْتُ نَفْسِي تَحْتَ أَكْبَرِ قِطْعَةِ لَحْمٍ.»','“Sonra kendimi en büyük et parçasının altına bağladım.”'),
('«فَجَاءَ نَسْرٌ كَبِيرٌ، وَحَمَلَ اللَّحْمَ وَحَمَلَنِي مَعَهُ!»','“Büyük bir kartal geldi; eti ve beni birlikte taşıdı!”'),
('«وَضَعَنَا النَّسْرُ فَوْقَ الْجَبَلِ، فَصَاحَ رَجُلٌ وَضَرَبَ بِعَصًا.»','“Kartal bizi dağın tepesine bıraktı; bir adam bağırdı ve sopayla vurdu.”'),
('«طَارَ النَّسْرُ، وَجَاءَ الرَّجُلُ، فَرَآنِي وَخَافَ.»','“Kartal uçtu, adam geldi; beni görünce korktu.”'),
('«قُلْتُ: لَا تَخَفْ، أَنَا إِنْسَانٌ مِثْلُكَ، وَعِنْدِي أَلْمَاسٌ كَثِيرٌ، فَخُذْ مِنْهُ.»','“Dedim ki: Korkma, ben de senin gibi bir insanım; bende çok elmas var, ondan al.”'),
('«فَفَرِحَ التَّاجِرُ، وَأَخَذَنِي إِلَى أَصْحَابِهِ، وَأَطْعَمُونِي.»','“Tüccar sevindi, beni arkadaşlarına götürdü ve beni doyurdular.”')]),
('الْعَوْدَةُ الثَّانِيَةُ','İkinci dönüş',[
('«سَافَرْتُ مَعَ هَؤُلَاءِ التُّجَّارِ إِلَى بِلَادٍ كَثِيرَةٍ.»','“Bu tüccarlarla birçok memlekete yolculuk ettim.”'),
('«وَبِعْتُ بَعْضَ الْأَلْمَاسِ، وَاشْتَرَيْتُ بِضَاعَةً جَمِيلَةً.»','“Elmasların bir kısmını sattım ve güzel mallar aldım.”'),
('«ثُمَّ وَصَلْنَا إِلَى الْبَصْرَةِ، وَمِنْهَا إِلَى بَغْدَادَ.»','“Sonra Basra’ya, oradan Bağdat’a vardık.”'),
('«فَرِحَ أَهْلِي، وَتَصَدَّقْتُ عَلَى الْفُقَرَاءِ وَالْأَيْتَامِ.»','“Ailem sevindi; fakirlere ve yetimlere sadaka verdim.”'),
('«وَنَسِيتُ تَعَبَ الطَّرِيقِ، وَقُلْتُ: لَنْ أُسَافِرَ مَرَّةً أُخْرَى.»','“Yolun yorgunluğunu unuttum ve dedim ki: Bir daha yolculuk etmeyeceğim.”'),
('ثُمَّ ضَحِكَ السِّنْدِبَادُ وَقَالَ لِلْحَمَّالِ: «لَكِنِّي سَافَرْتُ! تَعَالَ غَدًا، أَحْكِي لَكَ الرِّحْلَةَ الثَّالِثَةَ.»','Sonra Sindbad gülüp hamala dedi ki: “Ama yine yolculuğa çıktım! Yarın gel, sana üçüncü yolculuğu anlatayım.”'),
('وَأَعْطَاهُ مِئَةَ دِينَارٍ أُخْرَى، فَرَجَعَ الْحَمَّالُ إِلَى بَيْتِهِ سَعِيدًا.','Ona yüz dinar daha verdi; hamal da evine mutlu döndü.')]),
]
